<template><ion-page><ion-content class="auth-content"><main class="auth-card"><div class="auth-logo"><ion-icon :icon="personAddOutline" /></div><div class="brand"><span class="eyebrow">NOVA CONTA</span><h1>Crie sua<br><strong>galeria.</strong></h1><p>Organize cada momento especial.</p></div><ion-list lines="none"><ion-item><ion-input v-model="name" label="Nome" label-placement="stacked" placeholder="Seu nome" /></ion-item><ion-item><ion-input v-model="email" type="email" label="E-mail" label-placement="stacked" placeholder="voce@email.com" /></ion-item><ion-item><ion-input v-model="password" type="password" label="Senha" label-placement="stacked" placeholder="Mínimo de 4 caracteres" /></ion-item></ion-list><ion-button expand="block" class="auth-submit" @click="submit">Criar minha conta</ion-button><p class="auth-link">Já possui uma conta? <router-link to="/login">Entrar</router-link></p></main></ion-content></ion-page></template>
<script setup lang="ts">
import { ref } from 'vue'; import { IonButton, IonContent, IonIcon, IonInput, IonItem, IonList, IonPage, toastController } from '@ionic/vue'; import { personAddOutline } from 'ionicons/icons'; import { useRouter } from 'vue-router'; import { register } from '@/services/auth';
const router = useRouter(); const name = ref(''); const email = ref(''); const password = ref('');
async function submit() { if (!name.value.trim() || !email.value.trim() || password.value.length < 4) { const toast = await toastController.create({ message: 'Preencha os dados e use uma senha de ao menos 4 caracteres.', color: 'warning', duration: 2600 }); return toast.present(); } const result = await register({ name: name.value, email: email.value, password: password.value }); if (result.ok) { const toast = await toastController.create({ message: 'Conta criada. Agora entre com seu e-mail e senha.', color: 'success', duration: 2400 }); await toast.present(); return router.replace('/login'); } const toast = await toastController.create({ message: result.message, color: 'danger', duration: 2200 }); await toast.present(); }
</script>
